  const TH_ML = ['มกราคม', 'กุมภาพันธ์', 'มีนาคม', 'เมษายน', 'พฤษภาคม', 'มิถุนายน', 'กรกฎาคม', 'สิงหาคม', 'กันยายน', 'ตุลาคม', 'พฤศจิกายน', 'ธันวาคม'];
  const EN_ML = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];
  const MY_ML = ['ဇန်နဝါရီ', 'ဖေဖော်ဝါရီ', 'မတ်', 'ဧပြီ', 'မေ', 'ဇွန်', 'ဇူလိုင်', 'ဩဂုတ်', 'စက်တင်ဘာ', 'အောက်တိုဘာ', 'နိုဝင်ဘာ', 'ဒီဇင်ဘာ'];
  I.pattern(/^เป้าเดือน(\S+)$/, (m, L) => { const i = TH_ML.indexOf(m[1]); return i < 0 ? null : L2(L, `${EN_ML[i]} target`, `${MY_ML[i]} လ ပစ်မှတ်`); });
  I.pattern(/^ปิดได้ (\d+)%$/, (m, L) => L2(L, `${m[1]}% closed`, `${m[1]}% ပိတ်နိုင်ပြီ`));
