  I.pattern(/^จาก (.+)$/, (m, L) => L2(L, `From ${m[1]}`, `${m[1]} ထံမှ`));
  I.pattern(/^(.+) เปิดอ่านใบเสนอ (\d+) ครั้ง$/, (m, L) => L2(L, `${m[1]} opened the quote ${m[2]} times`, `${m[1]} ဈေးနှုန်းကို ${m[2]} ကြိမ် ဖွင့်ကြည့်ပြီး`));
  I.pattern(/^ยังไม่ตอบ · ห้องกันไว้ถึง (.+)$/, (m, L, t) => L2(L, `No reply yet · room held until ${t(m[1])}`, `မဖြေကြားရသေး · အခန်းကို ${t(m[1])} အထိ ထိန်းထားသည်`));
  I.pattern(/^(.+) จองชั่วคราวใกล้หมดอายุ$/, (m, L) => L2(L, `${m[1]} — tentative booking about to expire`, `${m[1]} — ယာယီကြိုတင်စာရင်း သက်တမ်းကုန်တော့မည်`));
  I.pattern(/^หมดอายุ (.+)$/, (m, L, t) => L2(L, `Expires ${t(m[1])}`, `သက်တမ်းကုန် ${t(m[1])}`));
