  I.pattern(/^แก้ไขข้อมูล (.+)$/, (m, L) => L2(L, `Edit ${m[1]}`, `${m[1]} ပြင်ရန်`));
  I.pattern(/^บันทึกข้อมูลของ (.+) แล้ว$/, (m, L) => L2(L, `${m[1]} saved`, `${m[1]} ၏ အချက်အလက် သိမ်းပြီး`));
  I.pattern(/^(ปิดใช้งาน|เปิดใช้งาน|ลบ)บัญชี (.+?)(\?| แล้ว)$/, (m, L) => {
    const v = { 'ปิดใช้งาน': ['Disable', 'ပိတ်', 'disabled'], 'เปิดใช้งาน': ['Enable', 'ဖွင့်', 'enabled'], 'ลบ': ['Delete', 'ဖျက်', 'deleted'] }[m[1]];
    return m[3] === '?' ? L2(L, `${v[0]} the account of ${m[2]}?`, `${m[2]} ၏ အကောင့်ကို ${v[1]}မလား?`) : L2(L, `Account of ${m[2]} ${v[2]}`, `${m[2]} ၏ အကောင့် ${v[1]}ပြီး`);
  });
  I.pattern(/^เพิ่ม (.+) แล้ว$/, (m, L) => L2(L, `${m[1]} added`, `${m[1]} ထည့်ပြီး`));
  I.pattern(/^เพิ่มบทบาท (.+) แล้ว$/, (m, L) => L2(L, `Role ${m[1]} added`, `${m[1]} အခန်းကဏ္ဍ ထည့်ပြီး`));
  I.pattern(/^ลบบทบาท (.+)\?$/, (m, L) => L2(L, `Delete role ${m[1]}?`, `${m[1]} အခန်းကဏ္ဍကို ဖျက်မလား?`));

