  I.pattern(/^(เพิ่ม|ลด) (.+)$/, (m, L, t) => L2(L, m[1] === 'เพิ่ม' ? 'Add ' : 'Remove ', m[1] === 'เพิ่ม' ? 'ထည့် ' : 'လျှော့ ') + (t(m[2]) || m[2]));
